# Per-row top-k and top-p (nucleus) logit masking for sampling: ascending sort, per-row k-th threshold, softmax + cumsum
# over sorted probs to drop the low-probability tail below 1-p (keeping at least one), scatter back to vocab order.
# Source: vllm-project/vllm vllm/v1/sample/ops/topk_topp_sampler.py (apply_top_k_top_p_pytorch), Apache-2.0.
import torch
import torch.nn as nn


def apply_top_k_top_p_pytorch(logits, k, p):
    logits_sort, logits_idx = logits.sort(dim=-1, descending=False)
    if k is not None:
        top_k_mask = logits_sort.size(1) - k.to(torch.long)
        top_k_mask = logits_sort.gather(1, top_k_mask.unsqueeze(dim=1))
        top_k_mask = logits_sort < top_k_mask
        logits_sort.masked_fill_(top_k_mask, -float("inf"))
    if p is not None:
        probs_sort = logits_sort.softmax(dim=-1)
        probs_sum = torch.cumsum(probs_sort, dim=-1, out=probs_sort)
        top_p_mask = probs_sum <= 1 - p.unsqueeze(dim=1)
        top_p_mask[:, -1] = False
        logits_sort.masked_fill_(top_p_mask, -float("inf"))
    return logits.scatter_(dim=-1, index=logits_idx, src=logits_sort)


class Model(nn.Module):
    def forward(self, logits, k, p):
        return apply_top_k_top_p_pytorch(logits.clone(), k, p)


